// Pre-match setup of the story match: dress the opponent's para_cp0010
// in kit 903, force the duel outcomes, and remove their Special Move whs0035.
BtlSetting <- function ()
{
	CMND_BTL_CHANGE_UNIFORM(1, "para_cp0010", 903, 0, 0, 903);
	CMND_BTL_CHANGE_UNIFORM(0, "para_cp0008", 1, 0, 18);
	CMND_BTL_SET_FORCE_WIN(true, 0, 1, true);
	CMND_BTL_SET_FORCE_WIN(true, 0, 0, true);
	CMND_BTL_SET_FORCE_WIN(true, "para_cp0010");
	CMND_BTL_FORGET_SKILL(1, "para_cp0010", "whs0035", false);
};

BtlSetting <- function ()
{
	// Target team 1 if it is CPU-controlled, otherwise team 0
	local cpu_team_id = 0;

	if (CMND_BTL_IS_CPU(1))
	{
		cpu_team_id = 1;
	}

	CMND_BTL_CHANGE_UNIFORM(cpu_team_id, "para_cp0010", 903, 0, 0, 903);
	CMND_BTL_FORGET_SKILL(cpu_team_id, "para_cp0010", "whs0035", false);
};
